const tabCode = (tab) => TAB_CODES[low(tab)] || low(tab).replace(/[^a-z0-9]+/g, '');
const parseTabs = (v) => String(v || 'Thực đơn').split(',').map((t) => t.trim()).filter(Boolean);
const colLetter = (i) => { let s = ''; for (let n = i + 1; n > 0; n = Math.floor((n - 1) / 26)) s = String.fromCharCode(65 + ((n - 1) % 26)) + s; return s; };
const qTab = (tab) => `'${String(tab).replace(/'/g, "''")}'`;
const batchQuery = (tabs) => tabs.map((t) => 'ranges=' + encodeURIComponent(`${qTab(t)}!A1:Z`)).join('&');
// valueRange -> { cols: {header: letter}, rows: [{...header: value, row_number}] }
const readTab = (vr) => {
  const values = (vr && vr.values) || [];
  const header = (values[0] || []).map((h) => String(h ?? '').trim());
  const cols = {};
  header.forEach((h, i) => { if (h) cols[h] = colLetter(i); });
  const rows = values.slice(1).map((r, i) => {
    const o = { row_number: i + 2 };
    header.forEach((h, j) => { if (h) o[h] = r[j] ?? ''; });
    return o;
  });
  return { cols, rows };
};
const cell = (tab, cols, header, row) => {
  if (!cols[header]) throw new Error(`Tab "${tab}" thiếu cột "${header}"`);
  return `${qTab(tab)}!${cols[header]}${row}`;
};
const PHONE = /(?:\+?84|0)(?:\d[\s.-]?){8,10}\d/;
const nowVN = () => new Date().toLocaleString('en-GB', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false }).replace(',', '');
const todayVN = () => new Date().toLocaleDateString('en-GB', { timeZone: 'Asia/Ho_Chi_Minh' });
// ---- end shared helpers ----

const cfg = {};
for (const item of $input.all()) {
  const key = item.json['Key'] ?? item.json['Khoá'] ?? item.json['Khóa'];
  if (key === undefined || key === null || String(key).trim() === '') continue;
  const value = item.json['Value'] ?? item.json['Giá trị'] ?? '';
  cfg[String(key).trim()] = typeof value === 'string' ? value.trim() : value;
}

const need = ['CMS_TYPE', 'SMTP_FROM', 'ADMIN_EMAIL', 'POSTER_EMAIL'];
if (String(cfg.CMS_TYPE || '').toLowerCase() === 'wordpress') need.push('WORDPRESS_URL');
const missing = need.filter((k) => !String(cfg[k] ?? '').trim());
if (missing.length) throw new Error('Config tab thiếu khoá: ' + missing.join(', '));
cfg.CMS_TYPE = String(cfg.CMS_TYPE).toLowerCase();
cfg.WORDPRESS_URL = String(cfg.WORDPRESS_URL || '').replace(/\/+$/, '');
// The WordPress password is sent to this URL, so anyone who can edit Config could redirect it.
// Only public https sites are accepted (protect the Config tab too).
if (cfg.CMS_TYPE === 'wordpress') {
  const m = cfg.WORDPRESS_URL.match(/^https:\/\/([^/:?#]+)(?::\d+)?(\/[^?#]*)?$/i);
  const host = m ? m[1].toLowerCase() : '';
  const internal = !host || !host.includes('.') || /^(localhost|winhost|n8n|postgres)$/.test(host) || /\.(local|internal|lan)$/.test(host)
    || /^(127\.|10\.|192\.168\.|169\.254\.|0\.)/.test(host) || /^172\.(1[6-9]|2\d|3[01])\./.test(host) || /^\[?[0-9a-f:]+\]?$/.test(host);
  if (internal) throw new Error('WORDPRESS_URL trong Config phải là địa chỉ https công khai của website (ví dụ https://truong.edu.vn)');
}
cfg.CONTENT_TABS = parseTabs(cfg.CONTENT_TABS).join(', ');
cfg.batch_query = batchQuery(parseTabs(cfg.CONTENT_TABS));
return [{ json: cfg }];

