// ---- end shared helpers ----

// Approved, not yet published rows across every content tab. "IF - Approved and Not Posted"
// re-checks the same conditions as a second guard (hard rule 2).
const cfg = $('Read Config').first().json;
const tabs = parseTabs(cfg.CONTENT_TABS);
const ranges = ($input.first().json.valueRanges) || [];
// WP_CATEGORIES: "Thực đơn=12; Thông báo=5"
const cats = {};
String(cfg.WP_CATEGORIES || '').split(/[;\n]/).forEach((p) => {
  const [k, v] = p.split('=');
  if (k && v && /^\d+$/.test(v.trim())) cats[low(k)] = Number(v.trim());
});
const out = [];
tabs.forEach((tab, t) => {
  const { cols, rows } = readTab(ranges[t]);
  for (const r of rows) {
    if (!truthy(r['Duyệt']) || truthy(r['Đã đăng']) || String(r['URL bài đăng'] ?? '').trim()) continue;
    if (!String(r['Bản website'] ?? '').trim()) continue;
    out.push({ json: {
      ...r,
      'Duyệt': true, 'Đã đăng': false,
      'Người duyệt': String(r['Người duyệt'] ?? '').trim() || 'không xác định (xem lịch sử phiên bản)',
      tab, row_number: r.row_number,
      title: `${tab} - ${r['Ngày']}`,
      wp_categories: cats[low(tab)] ? [cats[low(tab)]] : [],
      cell_posted: cell(tab, cols, 'Đã đăng', r.row_number), cell_url: cell(tab, cols, 'URL bài đăng', r.row_number),
      cell_note: cell(tab, cols, 'Ghi chú', r.row_number),
    } });
  }
});
return out;

