// ---- end shared helpers ----

// Mark every row published in this run, in one batchUpdate, and keep the audit rows.
const data = [], audit = [];
const stamp = nowVN();
for (const { json: r } of $input.all()) {
  data.push({ range: r.cell_posted, values: [[true]] });
  data.push({ range: r.cell_url, values: [[r.post_url]] });
  data.push({ range: r.cell_note, values: [[`${r.publish_method} - ${stamp}`]] });
  audit.push({ Timestamp: stamp, Tab: r.tab, Row: r.row_number, 'Content date': r.ngay, 'Approved by': r.approved_by,
    'Approved at': r.approved_at, Method: r.publish_method, 'Post URL': r.post_url, Result: 'SUCCESS' });
}
